"""Recompute the honest interrupted R01 prefix and seven preserved requests."""
import argparse,gzip,hashlib,json
from datetime import datetime
from pathlib import Path
def load(p):return json.loads(gzip.decompress(p.read_bytes())if p.suffix=='.gz'else p.read_bytes())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def calculate(root):
    result=load(root/'RESULTADO.json');cut=load(root/'CORTE_INTERRUMPIDO.json');rows=load(root/'REGISTROS_APD.json.gz');pro=load(root/'PROTOCOLO.json');events=[json.loads(x)for x in(root/'ADMISIONES_Y_EVENTOS.jsonl').read_text(encoding='utf8').splitlines()if x];checks={};issues=[]
    def check(label,ok):
        checks[label]=bool(ok)
        if not ok:issues.append(label)
    started=next(e for e in events if e['kind']=='owner_ready');stopped=next(e for e in events if e['kind']=='technical_control_result'and e['id']=='apd60_emergency_stop');stop=json.loads(stopped['record']['result']);elapsed=(datetime.fromisoformat(stop['finished_execution_utc'])-datetime.fromisoformat(started['utc'])).total_seconds();discount=sum(i['discount_seconds']for i in result['pause_intervals']);pending=[r for r in rows if r['status']in('queued','processing','uncertain')]
    check('original_harness_RESULTADO_unchanged',sha(root/'RESULTADO.json')==cut['original_RESULTADO_sha256']);check('recorded_failure_is_passive_WAL_size_race',result['error']['type']=='FileNotFoundError'and'cola.sqlite3-wal'in result['error']['detail']);check('actual_owner_stopped',cut['owner']['running']is False and stop['result']['graceful_stop']is True);check('actual_T188466_not_a_rewind',cut['main']['physical']['tick']==stop['after_tick']==188466 and result['before']['physical']['tick']==129652);check('seven_genuine_queued_rows_preserved',pending==cut['pending_rows']and len(pending)==7 and all(r['status']=='queued'for r in pending));check('no_uncertainty_reported',not cut['owner']['uncertain_external_result']);check('first_pause_recorded_without_native_advance',len(result['pause_intervals'])==1 and all(i['tick_preserved']for i in result['pause_intervals']));check('independent_actual_time_matches_witness',elapsed==cut['actual_owner_ready_to_stop_completion_seconds']and elapsed-discount==cut['observed_mode_enabled_seconds_before_technical_stop']);check('no_sixty_minute_claim',cut['sixty_minutes_claimed']is False and result['sixty_unpaused_minutes_reached']is False and elapsed<3600)
    attempted=[e for e in events if e['kind']in('admission','transport_validation_rejection')];lessons=[e for e in attempted if any(s.get('modo')=='apd-docencia'or s.get('operacion_memoria')=='revisar'for s in e['payload'].get('situaciones',[]))];check('new_words_and_beta_lesson_not_attempted',not lessons)
    native=load(root/'RECALCULO_SERVICIO_APD.json');check('raw_receipts_and_artifacts_have_no_recalculation_disagreement',not native['issues']);nominal={e['id']for e in pro['events']};attempted_ids={e['id']for e in attempted}
    return {'schema':'DEE.APD01.interrupted_prefix_recalculation.v1','sources':[{'file':f,'sha256':sha(root/f)}for f in('RESULTADO.json','CORTE_INTERRUMPIDO.json','REGISTROS_APD.json.gz','PROTOCOLO.json','ADMISIONES_Y_EVENTOS.jsonl','RECALCULO_SERVICIO_APD.json')],'checks':checks,'issues':issues,'owner_ready_to_graceful_stop_seconds':elapsed,'full_recorded_pause_discount_seconds':discount,'observed_mode_enabled_seconds':elapsed-discount,'sixty_minutes':False,'R01_minutes_credited_to_R02':0,'nominal_opportunities_attempted':len(nominal&attempted_ids),'nominal_opportunities_not_reached':len(nominal-attempted_ids),'native_receipts':native['native_receipts'],'material_request_outcomes':native['material_request_outcomes'],'preserved_real_queued_ids':[r['id']for r in pending],'scope':'Valid negative instrumental prefix. The original exception summary had no horizon field and computed zero minus pause; its negative estimate is retained but not interpreted as physical time. This calculation does not resume any queued action or add this time to R02.'}
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--evidencia',type=Path,required=True);p.add_argument('--salida',type=Path,required=True);a=p.parse_args();r=calculate(a.evidencia);a.salida.parent.mkdir(parents=True,exist_ok=True)
    with a.salida.open('x',encoding='utf8')as f:json.dump(r,f,sort_keys=True,ensure_ascii=False,indent=2);f.write('\n')
    print(json.dumps({'issues':r['issues'],'actual_seconds':r['observed_mode_enabled_seconds'],'sixty_minutes':False}));return bool(r['issues'])
if __name__=='__main__':raise SystemExit(main())
